import{_ as o,o as t,c as d,a6 as c}from"./chunks/framework.DIp0zHSV.js";const p=JSON.parse('{"title":"Home Assistant Services: Implementation Notes","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/internals/ha-services.md","filePath":"architecture/internals/ha-services.md","lastUpdated":1794278866000}'),a={name:"architecture/internals/ha-services.md"};function s(r,e,n,i,l,h){return t(),d("div",null,[...e[0]||(e[0]=[c(`<h1 id="home-assistant-services-implementation-notes" tabindex="-1">Home Assistant Services: Implementation Notes <a class="header-anchor" href="#home-assistant-services-implementation-notes" aria-label="Permalink to &quot;Home Assistant Services: Implementation Notes&quot;">​</a></h1><blockquote><p><strong>Architecture reference</strong>: how the <code>lcards.*</code> actions are registered, validated and delivered. For what each action does, with YAML and automation examples, see the <strong><a href="/dev/configuration/ha-actions.html">Home Assistant Actions user guide</a></strong>.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The integration registers 18 Home Assistant <strong>actions</strong> (formerly called services) in the <code>lcards</code> domain. <code>async_setup_services(hass)</code> runs in <code>async_setup_entry()</code> and <code>async_remove_services(hass)</code> in <code>async_unload_entry()</code>, so the actions exist only while the config entry is loaded (<a href="./../ha-integration.html#boot-sequence">boot sequence</a>).</p><p><strong>Source files:</strong></p><ul><li><code>custom_components/lcards/services.py</code>: one closure handler per action inside <code>async_setup_services()</code>, the <code>probatio</code> schemas, targeting resolution and the event helper.</li><li><code>custom_components/lcards/services.yaml</code>: names, descriptions and field selectors for Developer tools &gt; Actions and the automation editor. It is UI metadata only; validation is the schema in <code>services.py</code>.</li><li><code>src/core/services/IntegrationService.js</code>: the browser side of every action that is delivered as an event (<a href="./../subsystems/integration-service.html#handled-actions">Integration Service: Handled actions</a>).</li></ul><p>Two tests keep the files in step: <code>tests/docs/llms-txt.test.js</code> fails when the <code>SERVICE_*</code> names in <code>services.py</code> and the top-level keys of <code>services.yaml</code> differ, or when <code>doc/configuration/ha-actions.md</code> misses an action; <code>tests/core/borg-sound.test.js</code> checks that <code>_SOUND_EVENT_TYPES</code> and the <code>play_sound</code> selector offer the page sound events.</p><hr><h2 id="registration-and-schemas" tabindex="-1">Registration and Schemas <a class="header-anchor" href="#registration-and-schemas" aria-label="Permalink to &quot;Registration and Schemas&quot;">​</a></h2><p>Every action name is a <code>SERVICE_*</code> constant (<code>services.py:192-209</code>), listed in <code>_ALL_SERVICES</code> (<code>:211-230</code>) for removal, and registered with <code>hass.services.async_register(DOMAIN, name, handler, schema=...)</code> (<code>:540-691</code>). Schemas use <code>probatio</code> imported as <code>vol</code> (<code>services.py:53</code>), the voluptuous-compatible library Home Assistant uses since 2026.10. Home Assistant validates the call against the schema before the handler runs, so a bad field never reaches a handler; it is rejected with a validation error in the UI or the automation trace.</p><p>All 18 schemas include the four targeting fields (<code>_TARGET_FIELDS</code>, <code>services.py:96-101</code>): each an optional list of non-empty strings. Unknown fields are rejected (the schemas do not allow extra keys).</p><table tabindex="0"><thead><tr><th>Action</th><th>Schema (besides targeting)</th></tr></thead><tbody><tr><td><code>set_alert_mode</code></td><td><code>mode</code>: required, one of <code>_ALERT_MODES</code> (<code>green_alert</code>, <code>red_alert</code>, <code>yellow_alert</code>, <code>blue_alert</code>, <code>gray_alert</code>, <code>black_alert</code>)</td></tr><tr><td><code>red_alert</code>, <code>yellow_alert</code>, <code>blue_alert</code>, <code>gray_alert</code>, <code>black_alert</code>, <code>clear_alert</code></td><td>none</td></tr><tr><td><code>reload</code></td><td>none</td></tr><tr><td><code>set_log_level</code></td><td><code>level</code>: required, one of <code>LOG_LEVEL_OPTIONS</code> (<code>off</code>, <code>error</code>, <code>warn</code>, <code>info</code>, <code>debug</code>, <code>trace</code>)</td></tr><tr><td><code>trigger_effect</code></td><td><code>layers</code>: required dict; <code>duration</code>: int, at least 100 (ms)</td></tr><tr><td><code>clear_effect</code></td><td><code>slot</code>: one of <code>&quot;&quot;</code>, <code>backdrop</code>, <code>canvas</code>, <code>color</code></td></tr><tr><td><code>play_sound</code></td><td><code>event_type</code>: one of <code>_SOUND_EVENT_TYPES</code> (<code>services.py:78-88</code>, kept in step with <code>EVENT_CATEGORY</code> in <code>src/core/sound/SoundManager.js</code>); <code>asset_key</code>: non-empty string. Then <code>vol.Any</code>: an <code>event_type</code> or an <code>asset_key</code> is required (&quot;play_sound needs an event_type or an asset_key&quot;)</td></tr><tr><td><code>fly_to</code></td><td><code>card_id</code>: required non-empty string; <code>view</code>, <code>point</code>: non-empty strings; <code>duration</code>: int 0-60000; <code>warp</code>: bool. Then <code>vol.Any</code>: a <code>view</code> or a <code>point</code> is required (&quot;fly_to needs a view or a point&quot;)</td></tr><tr><td><code>set_clock</code></td><td><code>card_id</code>: required non-empty string; <code>date</code>: non-empty string; <code>rate</code>: a number (coerced to float), <code>&quot;live&quot;</code>, or a string with a unit matching <code>^-?\\d+(\\.\\d+)?\\s*(s|min|h|d|w|mo|y)\\s*(/\\s*s)?$</code> (for example <code>1 h/s</code>, <code>30 d/s</code>). Then <code>vol.Any</code>: a <code>date</code> or a <code>rate</code> is required (&quot;set_clock needs a date or a rate&quot;)</td></tr><tr><td><code>show_portal_card</code></td><td><code>content</code>: required dict; <code>layers</code>: dict; <code>position</code>: one of the nine positions (<code>top-left</code> ... <code>bottom-right</code>, <code>center</code>); <code>width</code>, <code>height</code>: strings; <code>duration</code>: int, at least 100; <code>dismiss</code>: bool</td></tr><tr><td><code>clear_portal_card</code></td><td>none</td></tr><tr><td><code>borg_assimilate</code></td><td><code>intro_duration</code>: int 1000-60000; <code>transition_style</code>: <code>flash</code>, <code>fade_only</code>, <code>blur_fade</code>, <code>off</code>; <code>site_count</code>, <code>tendrils_per_site</code>: int 1-20; <code>tendril_length</code>: int 100-1200; <code>particle_count</code>: int 0-6; <code>renderer</code>: <code>auto</code>, <code>webgl</code>, <code>canvas</code>; <code>cube</code>: <code>detailed</code>, <code>classic</code>, <code>none</code>; <code>corruption</code>, <code>overrun</code>: float 0-1; <code>suppress_persistent</code>, <code>font_swap</code>: bool; <code>palette_hue</code>: int 0-359 (coerced); <code>sound</code>: string; <code>intro_layers</code>, <code>persistent_layers</code>: dicts</td></tr><tr><td><code>borg_deassimilate</code></td><td><code>with_outro</code>: bool; <code>outro_layers</code>: dict; <code>revert_transition_style</code>: as <code>transition_style</code>; <code>sound</code>: string</td></tr></tbody></table><p><strong><code>clear_effect</code> &quot;All slots&quot;.</strong> The action form&#39;s slot selector has an &quot;All slots&quot; choice whose value is <code>&quot;&quot;</code> (<code>services.yaml</code>, <code>clear_effect.slot</code>), which is why the schema accepts the empty string. The handler turns <code>&quot;&quot;</code> and a missing slot alike into &quot;all&quot;: <code>slot = call.data.get(&quot;slot&quot;) or None</code>, and the payload carries <code>slot</code> only when it is set (<code>services.py:397-408</code>).</p><hr><h2 id="service-groups" tabindex="-1">Service Groups <a class="header-anchor" href="#service-groups" aria-label="Permalink to &quot;Service Groups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Actions</th><th>Handler pattern</th></tr></thead><tbody><tr><td><strong>Alert mode</strong></td><td><code>set_alert_mode</code>, <code>red_alert</code>, <code>yellow_alert</code>, <code>blue_alert</code>, <code>gray_alert</code>, <code>black_alert</code>, <code>clear_alert</code></td><td>Resolve targets. With targets: fire a <code>set_alert_mode</code> event (<code>{ mode }</code>) and leave the shared helper alone. Without: <code>_async_set_alert_mode(hass, mode)</code> (<code>services.py:233-252</code>), which checks that <code>input_select.lcards_alert_mode</code> exists and calls <code>input_select.select_option</code> with <code>blocking=True</code>. The shortcut actions are the same handler with a fixed mode (<code>clear_alert</code> = <code>green_alert</code>).</td></tr><tr><td><strong>Frontend control</strong></td><td><code>reload</code>, <code>set_log_level</code></td><td>Always events. <code>set_log_level</code> resolves its targets first, then sets the Python level on <code>custom_components.lcards</code> (process-wide, also for a targeted call) and fires <code>{ level }</code>; a target that matches nobody fails the call before the level changes. Neither changes the saved <code>log_level</code> option.</td></tr><tr><td><strong>Screen effects and sound</strong></td><td><code>trigger_effect</code>, <code>clear_effect</code>, <code>play_sound</code></td><td>Always events. <code>trigger_effect</code> sends <code>{ layers, duration? }</code> (<code>duration</code> only when truthy); <code>clear_effect</code> <code>{ slot? }</code>; <code>play_sound</code> <code>{ event_type?, asset_key? }</code>.</td></tr><tr><td><strong>Astrometrics</strong></td><td><code>fly_to</code>, <code>set_clock</code></td><td>Always events. The payload is <code>card_id</code> plus every other given field that is not <code>None</code> (<code>view</code>, <code>point</code>, <code>duration</code>, <code>warp</code>; <code>date</code>, <code>rate</code>).</td></tr><tr><td><strong>Portal overlay</strong></td><td><code>show_portal_card</code>, <code>clear_portal_card</code></td><td>Always events. <code>show_portal_card</code> always sends all seven keys, filling <code>position: &quot;center&quot;</code>, <code>width</code>/<code>height: &quot;auto&quot;</code> and <code>dismiss: true</code>, with <code>layers</code> and <code>duration</code> as <code>None</code> when not given.</td></tr><tr><td><strong>Borg</strong></td><td><code>borg_assimilate</code>, <code>borg_deassimilate</code></td><td>Always events, normalised first (below). Neither ever writes <code>input_select.lcards_alert_mode</code>, targeted or not: each browser switches its own palette to <code>borg_alert</code> through <code>ThemeManager.setAlertMode()</code> and returns to its previous alert mode on deassimilate.</td></tr></tbody></table><p>What the browser does with each payload, including the per-slot behaviour of <code>trigger_effect</code> (a slot left out is untouched, <code>null</code> clears it, <code>duration</code> gives each slot its own timer through <code>ScreenEffectManager.applySlotFor()</code>), is in <a href="./../subsystems/integration-service.html#handled-actions">Integration Service: Handled actions</a>.</p><h3 id="borg-payload-normalisation" tabindex="-1">Borg payload normalisation <a class="header-anchor" href="#borg-payload-normalisation" aria-label="Permalink to &quot;Borg payload normalisation&quot;">​</a></h3><p><code>handle_borg_assimilate</code> (<code>services.py:431-516</code>) builds the payload the browser expects:</p><ul><li>The flat shortcuts <code>site_count</code>, <code>tendrils_per_site</code>, <code>tendril_length</code>, <code>particle_count</code> become camelCase canvas params (<code>siteCount</code>, ...); <code>renderer</code>, <code>corruption</code> and <code>overrun</code> are copied as they are; <code>cube: none</code> becomes <code>cube: false</code>, <code>cube: detailed | classic</code> becomes <code>cube: true</code> plus <code>cubeStyle</code>.</li><li>Those go into <code>intro_layers.canvas</code>. When <code>intro_layers</code> is also given, its <code>canvas</code> keys win on overlap, after their snake_case keys are converted (<code>site_count</code>, <code>tendrils_per_site</code>, <code>tendril_length</code>, <code>particle_count</code>, <code>glow_color</code>, <code>cube_style</code>).</li><li><code>persistent_layers</code> is passed through; when it is absent, <code>suppress_persistent: true</code> sends <code>persistent_layers: {}</code>.</li><li><code>font_swap</code> is sent as <code>fontSwap</code>, <code>palette_hue</code> as <code>paletteHue</code> (the hue, 0-359 degrees, the palette shifts toward; the browser defaults to 110), <code>sound</code> only when non-empty.</li></ul><p><code>handle_borg_deassimilate</code> (<code>:518-536</code>) copies <code>with_outro</code>, <code>outro_layers</code>, <code>revert_transition_style</code> and a non-empty <code>sound</code>. How the browser maps these to <code>assimilate()</code> / <code>deassimilate()</code> options is in <a href="./../subsystems/borg-assimilation.html#action-payload-to-options">Borg Assimilation: Action payload to options</a>.</p><hr><h2 id="targeting" tabindex="-1">Targeting <a class="header-anchor" href="#targeting" aria-label="Permalink to &quot;Targeting&quot;">​</a></h2><p><code>_async_resolve_targets(hass, call)</code> (<code>services.py:105-168</code>) returns <code>(device_ids, user_ids)</code>:</p><ol><li>Start from <code>target_device_ids</code> and <code>target_user_ids</code> as given.</li><li><code>target_device_names</code>: lower-case each name and add every device whose <code>display_name</code> (lower-cased) in the <code>_device_&lt;id&gt;</code> storage records matches (<code>storage.get_namespaced_entities(&quot;_device&quot;)</code>). Several devices with the same name are all added. Without storage (entry not set up) a warning is logged and names resolve to nothing.</li><li><code>target_user_names</code>: lower-case and match against <code>user.name</code> of every user from <code>hass.auth.async_get_users()</code>.</li><li>If both lists are empty but any targeting field was given, raise <code>ServiceValidationError</code>. Otherwise return the lists (empty lists mean broadcast).</li></ol><p><code>_fire_targeted_event(hass, action, extra, device_ids, user_ids)</code> (<code>services.py:171-188</code>) fires <code>lcards_event</code> with <code>{ &quot;action&quot;: action, **extra }</code> and adds <code>target_device_ids</code> / <code>target_user_ids</code> only when non-empty, so a broadcast payload carries no target keys. Browsers keep an event when either list names them (union).</p><hr><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Raised by</th><th>Message</th><th>Result</th></tr></thead><tbody><tr><td>A field fails its schema (unknown mode, <code>duration</code> under 100, <code>palette_hue</code> 400, unknown field, ...)</td><td>Home Assistant, from the registered schema</td><td>the schema error</td><td>call rejected, handler not run</td></tr><tr><td><code>fly_to</code> with neither <code>view</code> nor <code>point</code></td><td>schema <code>vol.Any</code></td><td>&quot;fly_to needs a view or a point&quot;</td><td>rejected</td></tr><tr><td><code>set_clock</code> with neither <code>date</code> nor <code>rate</code></td><td>schema <code>vol.Any</code></td><td>&quot;set_clock needs a date or a rate&quot;</td><td>rejected</td></tr><tr><td><code>play_sound</code> with neither <code>event_type</code> nor <code>asset_key</code></td><td>schema <code>vol.Any</code></td><td>&quot;play_sound needs an event_type or an asset_key&quot;</td><td>rejected (before, it fired an event every browser ignored and the call reported success)</td></tr><tr><td>Targeting given but matches no device or user (a misspelt name, a device never registered, storage not loaded)</td><td><code>_async_resolve_targets()</code></td><td>&quot;LCARdS: no device or user matches the target (names: [...])&quot; (<code>ServiceValidationError</code>)</td><td>call fails; nothing is fired, never a broadcast (<code>set_log_level</code> leaves the Python level unchanged too)</td></tr><tr><td>Alert action without targeting, and <code>input_select.lcards_alert_mode</code> does not exist</td><td><code>_async_set_alert_mode()</code></td><td>&quot;LCARdS: input_select.lcards_alert_mode does not exist. Create the LCARdS helpers (LCARdS config panel, Helpers tab, Create All) and try again.&quot; (<code>ServiceValidationError</code>)</td><td>call fails (before, the call did nothing and still reported success)</td></tr><tr><td>Alert mode the helper does not offer as an option</td><td><code>input_select.select_option</code> (Home Assistant)</td><td>Home Assistant&#39;s own error</td><td>call fails (<code>blocking=True</code> passes it through)</td></tr><tr><td>Integration not set up</td><td>-</td><td>-</td><td>the <code>lcards.*</code> actions are not registered; automations calling them fail as unknown actions</td></tr></tbody></table><p><code>ServiceValidationError</code> shows as a user-facing error in the action UI and in the automation trace. A targeted alert action does not need the helper, so it never hits the missing-helper error.</p><p>Things that are not errors on the backend: <code>fly_to</code> / <code>set_clock</code> for a <code>card_id</code> no open dashboard shows fly or set nothing (each browser logs how many cards it reached).</p><hr><h2 id="push-channel-architecture" tabindex="-1">Push Channel Architecture <a class="header-anchor" href="#push-channel-architecture" aria-label="Permalink to &quot;Push Channel Architecture&quot;">​</a></h2><p>Eleven actions (<code>reload</code>, <code>set_log_level</code>, <code>trigger_effect</code>, <code>clear_effect</code>, <code>play_sound</code>, <code>fly_to</code>, <code>set_clock</code>, <code>show_portal_card</code>, <code>clear_portal_card</code>, <code>borg_assimilate</code>, <code>borg_deassimilate</code>) always go to the browsers as an event; the seven alert actions do only when targeting is given.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>handler (services.py)</span></span>
<span class="line"><span>  _async_resolve_targets()                    -&gt; (device_ids, user_ids) or ServiceValidationError</span></span>
<span class="line"><span>  _fire_targeted_event()</span></span>
<span class="line"><span>    hass.bus.async_fire(&quot;lcards_event&quot;, { action, ...payload, target_*? })</span></span>
<span class="line"><span>      Home Assistant event bus</span></span>
<span class="line"><span>        _forward() in ws_subscribe (websocket_api.py, @callback), once per subscription</span></span>
<span class="line"><span>          connection.send_message(event_message(id, event.data))</span></span>
<span class="line"><span>            every browser subscribed with lcards/subscribe</span></span>
<span class="line"><span>              IntegrationService._handleLcardsEvent(data)</span></span>
<span class="line"><span>                _isEventTargetedAtMe(payload)? no: drop</span></span>
<span class="line"><span>                switch (payload.action) ...</span></span></code></pre></div><p>Browsers subscribe with LCARdS&#39;s own <code>lcards/subscribe</code> command, open to non-admin users (Home Assistant&#39;s <code>subscribe_events</code> is admin-only for custom event types), so every dashboard receives the events. Delivery is always a broadcast; there is no per-connection delivery. More: <a href="./../ha-integration.html#python-to-js-push-channel">Python to JS Push Channel</a>.</p><hr><h2 id="adding-an-action" tabindex="-1">Adding an Action <a class="header-anchor" href="#adding-an-action" aria-label="Permalink to &quot;Adding an Action&quot;">​</a></h2><ol><li>Add a <code>SERVICE_*</code> constant and put it in <code>_ALL_SERVICES</code> (<code>services.py</code>).</li><li>Write the handler inside <code>async_setup_services()</code>: resolve targets with <code>_async_resolve_targets()</code>, build the payload (leave out fields that were not given), fire with <code>_fire_targeted_event()</code>.</li><li>Register it with a <code>probatio</code> schema that includes <code>**_TARGET_FIELDS</code>; enforce &quot;one of these fields is required&quot; in the schema (<code>vol.All(..., vol.Any(...))</code> as <code>fly_to</code> does) rather than in the browser.</li><li>Describe it in <code>services.yaml</code> (name, description, a selector per field, the four targeting fields). Descriptions are user-facing: &quot;Home Assistant&quot; in full, no em dashes.</li><li>Handle the <code>action</code> in <code>IntegrationService._handleLcardsEvent()</code>.</li><li>Document it in <code>doc/configuration/ha-actions.md</code> (the <code>llms-txt</code> test fails otherwise) and in the tables on this page and <a href="./../ha-integration.html#home-assistant-services-actions">Home Assistant Integration Architecture</a>.</li></ol><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/dev/configuration/ha-actions.html">Home Assistant Actions: User Guide</a>: what each action does, YAML and automation examples</li><li><a href="./../ha-integration.html">Home Assistant Integration Architecture</a>: boot sequence, WebSocket commands, push channel</li><li><a href="./../subsystems/integration-service.html">Integration Service</a>: the browser-side probe, subscription and handlers</li><li><a href="./../subsystems/borg-assimilation.html">Borg Assimilation</a>: what the Borg actions drive</li><li><a href="./../subsystems/helper-manager.html">Helper Manager</a>: how the browsers follow <code>input_select.lcards_alert_mode</code></li><li><a href="./../subsystems/theme-system.html#alert-mode-integration">Theme System: Alert Mode Integration</a>: how a browser applies an alert mode</li></ul>`,43)])])}const _=o(a,[["render",s]]);export{p as __pageData,_ as default};
